      // dearer end of that range, so it holds for any count inside it.
      let targetCount: TargetCountRange | undefined;
      let pricedAt = 0;
      let manaAffordable: boolean;
      const variantCost = this.castCostString(
        card,
        via,
        face,
        kicked,
        overload,
        free,
        altCost === true,
        costOption,
        player,
        graveyardGrant,
        offspring === true,
        evoke ?? null,
      );
      // Cast from the top of the library, a permission's filter can read X
