      if (spreeSets !== null && spreeSets.length === 0) continue;
      const specs = this.effectiveTargetSpecs(def, undefined, kicked, overload);
      const options = this.affordableTargetOptions(
        player,
        this.targetOptionsFor(specs, player, this.cardSource(def, card)),
      );
      // Rule 601.2c — a spell can't be cast without a legal target for every
      // slot that demands one. An *optional* slot ("up to one target
      // creature") with nothing to point at is simply skipped, so it never
      // blocks the cast. A targeted modal spell picks its slots per mode and
      // is gated by `castModalDescriptor` instead.
      if (
        def.castModal === null &&
        perX === null &&
        !targetsFillable(specs, options, [], 0, stateTargetFacts(this.state, this.registry))
      ) {
        continue;
      }
      const alternative = altCost === true ? this.alternativeCostOf(card, def, via, player) : null;
      const paidBase = evoke ?? printedOrPrototype;
      const cost = alternative !== null
        ? alternative.mana
        : free
        ? kicked && def.kicker !== null ? "{0}" + def.kicker.cost.repeat(kickCount ?? 1) : "{0}"
        : overload && def.overload !== null
          ? def.overload.cost
          : kicked && def.kicker !== null && paidBase !== null
            ? paidBase + def.kicker.cost.repeat(kickCount ?? 1) + (offspring === true ? (offspringCost ?? "") : "")
            : paidBase !== null && offspring === true
              ? paidBase + (offspringCost ?? "")
              : paidBase;
      const sacrifices = this.additionalCostSacrifices(
        player,
        def,
        costOption,
        this.graveyardPermissionSacrifice(player, card, face ?? 0, via, graveyardGrant),
      );
      const xPlan =
        parseManaCost(cost).x > 0 ? this.xPlanFor(player, card, def, cost, face ?? 0, pricedAt) : null;
      // "Sacrifice X creatures" (Eliminate the Competition): an X the mana
      // cost needn't have, as many as there are to sacrifice once the mana is
      // paid.
      const sacrificeXFilter =
        def.additionalCost?.sacrificeCount === "x" ? def.additionalCost.sacrifice : undefined;
      const sacrificeX =
        xPlan === null && sacrificeXFilter !== undefined
          ? (() => {
              const candidates = this.costSacrificeCandidates(player, [{ filter: sacrificeXFilter }], undefined);
              const plan = this.payMana(
                player,
                this.withFace(card, face ?? 0, () => this.castingCostOf(player, card, def, 0, cost, pricedAt)),
                undefined,
                undefined,
                { kind: "cast", card, face: face ?? 0 },
                { last: candidates },
              );
              if (plan === null) return 0;
              let n = 0;
              for (const left of this.costSacrificeLeftAfter(candidates, plan).values()) n += left;
              return n;
            })()
          : undefined;
